func (node *Proxy) Insert(ctx context.Context, request *milvuspb.InsertRequest) (*milvuspb.MutationResult, error) {
	ctx, sp := otel.Tracer(typeutil.ProxyRole).Start(ctx, "Proxy-Insert")
	defer sp.End()

	if err := merr.CheckHealthy(node.GetStateCode()); err != nil {
		return &milvuspb.MutationResult{Status: merr.Status(err)}, nil
	}

	log := log.Ctx(ctx).With(
		zap.String("role", typeutil.ProxyRole),
		zap.String("collection", request.CollectionName),
		zap.Int("len(FieldsData)", len(request.FieldsData)),
		zap.Uint32("NumRows", request.NumRows),
	)
	// NO VALIDATION of NumRows <= 100 found in this function
	it := &insertTask{
		ctx:       ctx,
		Condition: NewTaskCondition(ctx),
		insertMsg: &msgstream.InsertMsg{
			InsertRequest: &msgpb.InsertRequest{
				FieldsData: request.FieldsData,
				NumRows:    uint64(request.NumRows),
				// NumRows is passed through WITHOUT any range check
			},
		},
	}
}
